INSERT INTO `ANIMALI` (`IDanimale`, `Nome`, `DataNascita`, `DataRegistrazione`, `Sesso`, `Tipo`, `Colore`, `Pelo`, `Taglia`, `Razza`, `DescrFamiglia`, `DescrComportamentale`, `CondizioniMediche`, `Trasporto`, `ImgPath`, `Email`) VALUES
(1, 'Shaker', '2014-07-15', '2025-12-30', 'M', 'Cane', 'Bianco, Marrone', 'Corto', 'Medio', 'Jack russell terrier', 'molto molto calma...molto calma', 'Morde quando non gli dai la pizza, morde quando esci di case, distrugge tutti i giochi, le cucce e le coperte, trema sempre, ha sempre bisogno di coccole (gli piacciono i piedi), penso sia pazzo per colpa della famiglia precedente', NULL, 1, 'assets/images/animals/bobo.png', 'lindorlinor@gmail.com'),
(6, 'Kiba', '2016-01-16', '2026-01-12', 'M', 'Cane', 'Dorato', 'Lungo', 'Grande', 'Golden retriver', 'Preferisce le famiglie grandi, i bambini lo adorano, gli piace uscire e giocare e soffre molto la solitudine', 'Appassionato di coccole, fa gli occhi dolci per un pezzo di carne. Non abbaia quasi mai, e sporca pochissimo', 'Dermatite facile', 1, './assets/images/animals/kiba.jpg', 'lindorlinor@gmail.com'),
(42, 'Maurice Ravel', '2016-10-15', '2026-01-24', 'M', 'Gatto', 'Nero', 'Corto', 'Medio', 'Meticcio', 'Idealmente una famiglia che non abbia bambini piccoli perché potrebbe fargli involontariamente male. Ma qualsiasi altro tipo di ambiente va bene.', 'Ha sicuramente qualche problema psichiatrico. Può essere comparato ad uno scienziato pazzo; ama conoscere tutta l’oggettistica e il mobilio della casa; se arriva un nuovo oggetto deve essere ispezionato da lui (anche a costo di frantumarlo in mille pezzi). \r\nE’ molto simpatico; può sembrare mono-espressivo ma in realtà è un tenerone capace di dare tantissimo affetto.\r\nAma il contatto con gli umani e cerca sempre di essere presente nelle situazioni di convivialità anche con gli ospiti.\r\nBisogna fare attenzione perché è un giocherellone e a volte morde senza preavviso (essendo lui grande può fare male). \r\nIl suo migliore amico è un cagnolino di nome Totò; va d’accordo con tutti gli animali.', '0', 1, 'assets/images/animals/maurice.jpeg', 'lindorlinor@gmail.com'),
(43, 'Olly', '2018-10-09', '2026-01-24', 'M', 'Cane', 'Tigrato', 'Corto', 'Grande', 'Corso, Labrador', 'Una famiglia di adulti, in grado di dargli le attenzioni che merita. \r\nHa bisogno di spazio per potersi muovere e di tempo per poterlo accudire al meglio. \r\nNon è assolutamente adatto a bambini e anziani.', 'È un cane molto diffidente; da piccolo ha subito diversi abusi quindi difficilmente riesce ad essere amichevole. \r\nSe farete parte del suo branco vi amerà e proteggerà incondizionatamente.\r\nÈ un furbacchione, sa di essere alto e quindi tende a cercare di fregarvi il cibo; inoltre è molto simpatico e gli piace fare i dispetti. \r\nAma giocare e correre. E non vi lascerà mai soli, quando si affeziona ad una persona rimarrà per sempre sotto la sua ala protettiva. Davvero un’anima gentile. \r\nÈ estremamente intelligente e nonostante le sue moltissime paure riesce a comprendere le situazioni che lo circondano (anche quelle più fragili).', '0', 1, 'assets/images/animals/olly.jpeg', 'angelafavaro6@gmail.com'),
(44, 'Totò', '2014-09-01', '2026-01-24', 'M', 'Cane', 'Biondo', 'Medio', 'Medio', 'Meticcio', 'Una famiglia che non abbia bambini molto piccoli; dai 10 anni in sù non ci sono problemi.', 'È un cagnolino molto amichevole! Ama la compagnia delle persone, a patto che non siano bambini (quelli proprio non gli vanno a genio…).\r\nNon è particolarmente agile ed è un vero pigrone! Anche se il veterinario vi dirà che deve muoversi, quindi passeggiate obbligatorie (ha la prova costume da fare!).\r\nNon ama la compagnia di altri cagnolini, dopo che da piccolo ha perso il suo fratellino Beppe è diventato molto diffidente nei confronti degli altri cani. In compenso adora le persone ed è estremamente tranquillo.', '0', 0, 'assets/images/animals/toto.jpg', 'lindorlinor@gmail.com'),
(45, 'Briscola', '2009-09-18', '2026-01-24', 'F', 'Gatto', 'Nero', 'Medio', 'Medio', 'Meticcio', 'Una famiglia tranquilla, cerca una persona che sia in grado di darle tanto affetto.', 'Ama le coccole e il divano. Non c\'è molto altro da dire. \r\nAh, ogni tanto si dimentica che deve mangiare, quindi è meglio ricordarglielo. È una pigrona e farà di tutto per muoversi il meno possibile ma è più agile di quello che mostra...non fatevi fregare. \r\nSe avete paura che scappi tranquilli, non scappa. Odia tutti gli altri animali esistenti al mondo. Ama tutti gli umani esistenti al mondo.', '0', 1, 'assets/images/animals/briscola.jpg', 'lindorlinor@gmail.com'),
(49, 'Haiiro', '2025-10-24', '2026-01-24', 'M', 'Cane', 'Grigio', 'Corto', 'Piccolo', 'Levriero Italiano', 'Preferibilmente una casa grande con spazi esterni estesi.', 'È un po\' pazzo. Saltella e si muove un po\' sbilenco! Allegro e giocoso.', '0', 1, 'assets/images/animals/haiiro.jpeg', 'lindorlinor@gmail.com'),
(50, 'Smoky', '2015-10-07', '2026-01-25', 'M', 'Gatto', 'Grigio Tigrato', 'Corto', 'Piccolo', 'Meticcio', 'Cerca alloggio lontano dalla piena città (sarebbe pericoloso per un gatto che va spesso fuori).', 'È un gatto con un indole selvaggia. Preferisce di gran lunga stare all\'aria aperta agli spazi chiusi. Ama le coccole, ma alle sue condizioni (rigorosamente NON in braccio) e quando vuole lui.\r\nOra che si sta facendo vecchietto sta iniziando a godersi anche gli ambienti coperti oltre alla natura.', '0', 0, 'assets/images/animals/smoky.jpg', 'angelafavaro6@gmail.com'),
(58, 'Shaker', '2014-07-14', '2026-01-26', 'M', 'Cane', 'Bianco E Marrone', 'Corto', 'Medio', 'Juck Russell', 'Una famiglia crazy che urla PIZZA quando arriva la pizza', 'He crazy. Ha bisogno di un sacco di attenzioni. Piange sempre. PIANGE SEMPRE. Ti sveglia alle 3 di notte perché ha bisogno di fare plin plin. Se dici PIZZA impazzisce.', '0', 0, 'assets/images/animals/shaker.jpg', 'lindorlinor@gmail.com'),
(59, 'Key', '2014-03-26', '2026-01-26', 'M', 'Cane', 'Marrone E Nero', 'Lungo', 'Piccolo', 'Yorkshire Terrier', 'Una famiglia che lo tratti come il re della casa.', 'Territoriale. Non ama gli altri animali. Gli piace stare in auto.', 'Sterilizzato, problemi di stomaco e gola', 1, 'assets/images/animals/key.jpg', NULL),
(60, 'Briciola', '2025-05-15', '2026-01-26', 'F', 'Gatto', 'Tigrato', 'Medio', 'Piccolo', 'Non ne ho idea', 'La mia angela', 'So che è una pazza', 'Guarda sta benissimo', 1, 'assets/images/animals/briciola.jpg', NULL),
(61, 'Lilli', '2012-05-08', '2026-01-26', 'F', 'Cane', '', 'Corto', 'Medio', 'Meticcio', 'Qualcuno a cui piaccia camminare molto, con il tempo di portare per lunghe passeggiate il proprio cane. È preferibile che non possieda altri animali.', 'Un cane tranquillo che adora fare passeggiate. Affettuosa con le persone, ma gli altri animali domestici le stanno proprio antipatici. Cerca sempre di rubare il cibo ai gatti. \n', 'Dermatite ricorrente', 0, 'assets/images/animals/lilli.jpg', NULL),
(62, 'Nuvola', '2016-01-26', '2025-05-07', 'F', 'Cane', 'Bianco e nero', 'Medio', 'Piccolo', 'Shih Tzu', 'Preferibilmente che sia paziente e servile', 'È una piccola principessina, dotata di un notevole udito selettivo\r\n', 'Manca degli incisivi superiori e inferiori, ha quindi sempre la lingua fuori.', 0, 'assets/images/animals/nuvola.jpg', NULL),
(63, 'Miles', '2025-01-26', '2025-12-07', 'M', 'Gatto', 'Nero', 'Corto', 'Medio', 'Meticcio', 'Qualcuno a cui non dia fastidio se un gatto lo segue in bagno e poi lo fissa intensamente mentre fa i suoi bisogni.', ' È proprio un ruffiano. Molto coccoloso, SOPRATTUTTO se c’è del cibo a portata di mano ma non di zampa. Quando fa le fusa sembra un trattore. Ha una strana ossessione per il water.', 'Otite', 0, 'assets/images/animals/miles.jpg', NULL),
(64, 'Bianca', '2021-01-13', '2025-11-20', 'F', 'Cane', 'Dorato', 'Medio', 'Grande', 'Bassotto', 'Una famiglia che ami giocare all\'aperto. ', 'Giocosa', NULL, 1, 'assets/images/animals/bianca.jpg', NULL),
(65, 'Ariel', '2024-01-12', '2026-01-25', 'F', 'Gatto', 'Bianco', 'Corto', 'Medio', 'Khao Manee', 'Da scrivere', 'Da scrivere', NULL, 1, './assets/images/animals/ariel.jpg', NULL),
(66, 'Romeo', '2024-01-18', '2026-01-26', 'M', 'Gatto', 'Tigrato', 'Medio', 'Piccolo', 'Meticcio', 'Da scrivere', 'Da scrivere', NULL, 1, './assets/images/animals/romeo.jpg', NULL),
(67, 'Pandora', '2020-01-18', '2026-01-20', 'F', 'Cane', 'Nero a chiazze bianche e marroni', 'Corto', 'Medio', 'Meticcio', 'Da scrivere', 'Da scrivere', NULL, 1, './assets/images/animals/pandora.jpg', NULL);
