INSERT INTO `RICHIESTE_ADOZIONI` (`Email`, `IDanimale`, `Trasporto`, `Appunti`, `LetteraPresentazione`, `Stato`, `DataRichiesta`, `DataFineValutazione`, `DataInizioValutazione`) VALUES
('angelacanazza2005@gmail.com', 1, 1, 'raga che bello \r\nposso andare a capo', 'voglio un cagnolino. adesso.', 'Da trasportare', '2026-01-05', '2026-01-26', '2026-01-26'),
('angelacanazza2005@gmail.com', 44, 0, 'Lettera di presentazione non conforme alle aspettative.', 'aaa', 'Annullata', '2026-01-05', '2026-01-26', '2026-01-26'),
('angelafavaro6@gmail.com', 43, 0, NULL, 'Ciao voglio Ollu', 'Nuova', '2026-01-26', NULL, NULL),
('lindorlinor@gmail.com', 42, 0, NULL, 'kieiwofefdjifjelfjeailfjslifjsilfjsilfjslfjdkldsjfklsjkfldsldkfs', 'Respinta', '2026-01-25', '2026-01-26', '2026-01-26'),
('linor.sade@studenti.unipd.it', 1, 0, 'Aiuto questa rivuole indietro il suo cane, cosa posso fare...le dico che non può...', 'Ciao vorrei indietro il mio cane. È così carino. Oggi gli ho comprato un giubbottino nuovo e quindi mi piacerebbe portarlo in giro con quello. Poi le altre persone non sono al sicuro con lui...non sanno come si comporta quando c\'è la pizza...ed è meglio che non lo scoprano impreparati...RIDAMMI IL CANE È MIO', 'Accettata', '2026-01-09', '2026-01-20', '2026-01-18'),
('linor.sade@studenti.unipd.it', 43, 0, NULL, 'pls pls pls pls pls', 'Nuova', '2026-01-26', NULL, NULL),
('linor.sade@studenti.unipd.it', 49, 1, NULL, 'Ciao! Mi sto traferendo in una nuova casa e ora ho la possibilità di avere due cani! Il mio primo cane lo ho adottato proprio da voi e sono rimasta soddisfatta della cura che avete avuto. Veniamo al punto: ho deciso di adottare un nuovo cagnolino perchè il mio attuale ha bisogno di un po\' di compagnia! Va molto d\'accordo con i levrieri italiani ed è molto curioso di fare nuove amicizie!', 'Annullata', '2026-01-26', '2026-01-26', NULL),
('linor.sade@studenti.unipd.it', 58, 1, 'mi sembra appropriata questa adozione. La lettera di presentazione precedente non la ho cercata e non gliela ho chiesta ma direi che va bene così!', 'Ho precedentemente inviato una richiesta per un altro cane ma mi sono accorta che questo è esattamente uguale a quello che ho già! Anche il nome! Significa che posso chiamarne uno e arrivano entrambi!!!!! Sono emozionata lo voglio subito datemelo pls', 'In valutazione', '2026-01-26', NULL, '2026-01-26'),
('porcoventi@gmail.com', 6, 0, NULL, 'Voglio tantissimo questo cane perché sennò sono sempre da solo ho bisogno di un amico', 'Respinta', '2026-01-21', '2026-01-26', '2026-01-26'),
('porcoventi@gmail.com', 42, 1, 'Sembra un tizio estremamente affidabile', 'Maurice sembra il mio dream cat', 'In valutazione', '2026-01-24', '2026-01-24', '2026-01-24'),
('porcoventi@gmail.com', 43, 1, 'Aiuto quando la smette questo', 'LI VOGLIO COLLEZIONARE TUTTI', 'Da trasportare', '2026-01-24', '2026-01-24', '2026-01-24'),
('porcoventi@gmail.com', 44, 0, NULL, 'L\'altro non esiste quindi provo con questo', 'Annullata', '2026-01-24', '2026-01-24', '2026-01-24'),
('porcoventi@gmail.com', 49, 0, 'Non date più animali a sto qua. \r\nho respinto la richiesta perchè non è adatto\r\nall\'animale.', 'Ehi! Sono ancora io! Mi avete rifiutato l\'ultima richiesta quindi ora chiedo questo qui', 'In valutazione', '2026-01-25', NULL, '2026-01-26');
